package review.dual;
import review.mysql.*;
import ai_study_planner.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.mock.web.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import javax.sql.DataSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class DualLedgerDiagnosticTests {
 final DualLedgerDiagnostics d=new DualLedgerDiagnostics();
 String json(Object o)throws Exception{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(o);}
 @Test void typedHttpFailureSeparatesInputFromScenario()throws Exception{d.enter("FIRST_LOG");var r=mock(org.springframework.test.web.servlet.MvcResult.class);var response=new MockHttpServletResponse();response.setStatus(503);response.getWriter().write("{\"code\":\"IDEMPOTENCY_STORAGE_UNAVAILABLE\",\"message\":\"secret-password-sentinel\"}");when(r.getResponse()).thenReturn(response);var e=assertThrows(DualLedgerDiagnostics.Failure.class,()->d.expect(r,200,"FIRST_LOG"));var proof=d.failure(e);assertEquals("FIRST_LOG",proof.get("scenarioStep"));assertEquals(503,proof.get("actualHttpStatus"));assertEquals("HTTP_EXPECTATION_IDEMPOTENCY_STORAGE_UNAVAILABLE",proof.get("code"));assertFalse(json(proof).contains("secret-password"));}
 @Test void unknownApiCodeNeverLeaksResponseBody()throws Exception{d.enter("DAILY");var r=mock(org.springframework.test.web.servlet.MvcResult.class);var response=new MockHttpServletResponse();response.setStatus(500);response.getWriter().write("{\"code\":\"SECRET_API_KEY_SENTINEL\"}");when(r.getResponse()).thenReturn(response);var e=assertThrows(Exception.class,()->d.expect(r,200,"DAILY"));assertFalse(json(d.failure(e)).contains("SECRET_API"));}
 @Test void wrappedSqlFailureSurvivesMaskedBusinessExceptionWithoutExtraSql()throws Exception{var source=mock(DataSource.class);var c=mock(Connection.class);var q=mock(PreparedStatement.class);when(source.getConnection()).thenReturn(c);when(c.prepareStatement("synthetic SQL secret")).thenReturn(q);when(q.executeUpdate()).thenThrow(new SQLException("password=secret-sentinel","42000",1142));d.enter("FIRST_LOG");try(var observed=d.wrap(source).getConnection();var statement=observed.prepareStatement("synthetic SQL secret")){assertThrows(SQLException.class,statement::executeUpdate);}var proof=d.failure(new StudyLogIdempotencyFailure(503,"IDEMPOTENCY_STORAGE_UNAVAILABLE","masked"));assertEquals("SQL_PRIVILEGE",proof.get("sqlCategory"));assertEquals(1142,proof.get("mysqlErrorNumber"));assertEquals("42000",proof.get("jdbcSqlState"));assertFalse(json(proof).contains("sentinel"));assertFalse(json(proof).contains("synthetic SQL"));verify(c,times(1)).prepareStatement("synthetic SQL secret");verify(q,times(1)).executeUpdate();verify(c).close();}
 @Test void causeAndNextExceptionAreBoundedAndSafe()throws Exception{var one=new SQLException("secret-1");var two=new SQLException("secret-2","HY000",1213);one.setNextException(two);var proof=d.failure(new java.util.concurrent.ExecutionException(one));assertEquals("SQL_LOCK",proof.get("sqlCategory"));assertFalse(json(proof).contains("secret-"));}
 @Test void invalidSqlStateAndNumberAreSanitized(){var note=DualLedgerDiagnostics.sqlNote(new SQLException("secret","jdbc:mysql:secret",-99));assertEquals("UNAVAILABLE",note.get("jdbcSqlState"));assertEquals(0,note.get("mysqlErrorNumber"));}
 @Test void stepAndFailureCodesCannotCarrySecrets()throws Exception{d.enter("secret-password");var e=new DualLedgerDiagnostics.Failure("secret-key","secret-code",0,0);var proof=d.failure(e);assertEquals("UNCLASSIFIED",proof.get("scenarioStep"));assertEquals("UNCLASSIFIED_FAILURE",proof.get("code"));assertFalse(json(proof).contains("secret"));}
 @Test void journalPublishesOnlyAllowlistedStepEvents(@TempDir Path p)throws Exception{d.journal(p);d.enter("LOGIN");d.enter("FIRST_LOG");d.complete();try(var files=Files.list(p.resolve("scenario-checkpoints"))){var paths=files.toList();assertEquals(3,paths.size());for(Path f:paths){var tree=review.mobile.GeminiShutdown.validJson(Files.readAllBytes(f));assertTrue(Set.of("ENTER","COMPLETE").contains(tree.path("event").asText()));assertFalse(tree.has("password"));}}}
 @Test void journalCannotOverwriteExistingEvidence(@TempDir Path p)throws Exception{Files.createDirectory(p.resolve("scenario-checkpoints"));Files.writeString(p.resolve("scenario-checkpoints/original.json"),"original");assertThrows(Exception.class,()->d.journal(p));assertEquals("original",Files.readString(p.resolve("scenario-checkpoints/original.json")));}
 @Test void publicationFailureHasSafeStepCode(@TempDir Path p)throws Exception{d.journal(p);Files.writeString(p.resolve("scenario-checkpoints/000001.json"),"original");var failure=assertThrows(DualLedgerDiagnostics.Failure.class,()->d.enter("DAILY"));assertEquals("DIAGNOSTIC_PUBLICATION_FAILED",d.failure(failure).get("code"));assertEquals("original",Files.readString(p.resolve("scenario-checkpoints/000001.json")));}
 @Test void anyStorage503IsNotSuccessfulInjectedRollback(){var e=new StudyLogIdempotencyFailure(503,"IDEMPOTENCY_STORAGE_UNAVAILABLE","masked");assertThrows(DualLedgerDiagnostics.Failure.class,()->DualLedgerScenario.rollbackFailure(e,false));assertDoesNotThrow(()->DualLedgerScenario.rollbackFailure(e,true));}
 @Test void successfulJdbcCallsAndProxyIdentityAreUnchanged()throws Exception{var source=mock(DataSource.class);var nativeC=mock(Connection.class);when(source.getConnection()).thenReturn(nativeC);var c=d.wrap(source).getConnection();assertTrue(c.equals(c));assertEquals("DualLedgerObservedJdbc",c.toString());c.setAutoCommit(false);c.commit();c.close();verify(nativeC).setAutoCommit(false);verify(nativeC).commit();verify(nativeC).close();assertFalse(d.failure(new RuntimeException("secret")).containsKey("jdbcSqlState"));}
 @Test void nextStepDoesNotMisattributeAnOldSqlFailure(){d.enter("DAILY");d.sql(new SQLException("hidden","HY000",1213));d.enter("SUMMARY");assertFalse(d.failure(new RuntimeException()).containsKey("mysqlErrorNumber"));}
}
